#!/usr/bin/env python3
"""immuno/allergen_predict — auto-generated run.py (archetype=mhc_epitope).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "mhc_epitope"
BRAIN = "immuno"
SKILL = "allergen_predict"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'allergen_predict', 'n_epitopes': 0, 'epitopes_csv': '', 'diagnostics': {'brain': 'immuno', 'archetype': 'mhc_epitope'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Allergen 预测简化版:对 query 序列与已知 allergen 数据库做 BLAST identity 比较。
    host_env=praxis-immuno(无 AllerTOP/AllergenFP,降级 BLAST-based heuristic)。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    seq = payload.get("sequence")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "BLAST-identity (simplified)",
                   "note": "host 无 AllerTOP/AllergenFP; 用 35% identity / 6 contiguous AA heuristic"}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_epitopes": 0, "epitopes_csv": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not seq:
        return {"ok": False, "error": "需要 sequence", "diagnostics": diagnostics}
    # FAO/WHO allergen criteria: 35% identity over 80-mer window, or 6 contiguous amino acid match
    # 用户需提供 allergen_db 路径(BLAST formatted)
    blast_db = payload.get("allergen_blast_db")
    if not blast_db:
        return {"ok": True, "skill_id": SKILL,
                "n_epitopes": 0, "epitopes_csv": "",
                "diagnostics": {**diagnostics, "note": "no allergen_blast_db given; 返 empty"}}
    fa = _tempfile.NamedTemporaryFile(mode="w", suffix=".fa", delete=False)
    fa.write(f">query\n{seq}\n"); fa.close()
    out_tsv = _tempfile.NamedTemporaryFile(suffix=".tsv", delete=False).name
    t0 = _time.time()
    r = run_tool(["blastp", "-query", fa.name, "-db", blast_db, "-out", out_tsv,
                  "-outfmt", "6 qseqid sseqid pident length evalue bitscore",
                  "-evalue", "1e-5"],
                 timeout=int(payload.get("timeout_s", 600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "blastp 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    hits = []
    if _os.path.isfile(out_tsv):
        with open(out_tsv) as fh:
            for ln in fh:
                fields = ln.strip().split("\t")
                if len(fields) >= 6:
                    pid = float(fields[2]); ln_ = int(fields[3])
                    if pid >= 35 and ln_ >= 80:
                        hits.append({"subject": fields[1], "pident": pid, "len": ln_, "evalue": fields[4]})
    return {"ok": True, "skill_id": SKILL,
            "n_epitopes": len(hits), "epitopes_csv": out_tsv,
            "allergen_hits": hits,
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
